class DishTracker {
    private final AtomicReference<DishStatus> current = new AtomicReference<>(DishStatus.WAITING);
    private final Sinks.Many<DishStatus> status = Sinks.many().replay().latestOrDefault(DishStatus.WAITING);
    private final Sinks.Many<Transition> transitions = Sinks.many().multicast().onBackpressureBuffer(64, false);

    public DishStatus currentStatus() { return current.get(); }                   // 1. a synchronous read
    public Flux<DishStatus> status() { return status.asFlux().distinctUntilChanged(); }
    public Flux<Transition> transitions() { return transitions.asFlux(); }

    boolean moveTo(DishStatus next) {
        DishStatus from = current.get();
        if (!from.canMoveTo(next) || !current.compareAndSet(from, next)) return false;   // 2. atomic move
        // 3. sinks reject concurrent emits (FAIL_NON_SERIALIZED), so serialize them
        synchronized (this) {
            status.tryEmitNext(next);
            transitions.tryEmitNext(new Transition(dish, from, next));
        }
        return true;
    }
}

kotlin.src:
class DishTracker(private val dish: String) {
    val status: StateFlow<DishStatus>                         // 1. .value is a synchronous read
        field = MutableStateFlow(DishStatus.WAITING)
    val transitions: SharedFlow<Transition>
        field = MutableSharedFlow(extraBufferCapacity = 64)

    fun moveTo(next: DishStatus): Boolean {
        while (true) {
            val from = status.value
            if (!from.canMoveTo(next)) return false
            if (status.compareAndSet(from, next)) {           // 2. atomic move
                check(transitions.tryEmit(Transition(dish, from, next)))   // 3. safe from any thread
                return true
            }
        }
    }
}

