    val state: StateFlow<AlarmState>
        field = MutableStateFlow(AlarmState.QUIET)

    val events: SharedFlow<String>
        field = MutableSharedFlow(extraBufferCapacity = 64)

    fun trip(): Boolean {
        if (!state.compareAndSet(AlarmState.QUIET, AlarmState.RINGING)) return false
        check(events.tryEmit("alarm ringing"))
        return true
    }
}

