// Java equivalent: an atomic holder for the state, a buffered multicast sink for events
class SmokeAlarm {
    private final AtomicReference<AlarmState> state = new AtomicReference<>(AlarmState.QUIET);
    private final Sinks.Many<String> events = Sinks.many().multicast().onBackpressureBuffer(64, false);

    AlarmState state() { return state.get(); }
    Flux<String> events() { return events.asFlux(); }

    synchronized boolean trip() {   // synchronized: Reactor sinks reject concurrent emits
        if (!state.compareAndSet(AlarmState.QUIET, AlarmState.RINGING)) return false;
        events.tryEmitNext("alarm ringing").orThrow();
        return true;
    }
}
